def fib4(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the base cases
    fib4_values = [0, 0, 2, 0]

    # Compute the sequence iteratively
    for i in range(4, n + 1):
        fib4_values.append(fib4_values[i - 1] + fib4_values[i - 2] + fib4_values[i - 3] + fib4_values[i - 4])

    return fib4_values[n]
```

