class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

class BinaryTree:
    def __init__(self):
        self.root = None

    def add_node(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._add_node(value, self.root)

    def _add_node(self, value, node):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._add_node(value, node.left)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._add_node(value, node.right)
        else:
            node.children.append(value)

    def pluck(self):
        if self.root is None:
            return []

        smallest_even = float('inf')
        smallest_node = None

        def find_smallest_even(node, index):
            nonlocal smallest_even, smallest_node
            if node.value == smallest_even and index < smallest_node[1]:
                smallest_node = (node.value, index)
            elif node.value % 2 == 0 and node.value < smallest_even:
                smallest_even = node.value
                smallest_node = (node.value, index)
            for child in node.children:
                find_smallest_even(child, index + 1)

        find_smallest_even(self.root, 0)
        return list(smallest_node)

