def encode(message):
    def swap_case(c):
        if c.islower():
            return c.upper()
        else:
            return c.lower()

    def replace_vowel(c):
        vowels = "aeiou"
        if c.lower() in vowels:
            index = vowels.index(c.lower())
            if c.islower():
                return vowels[(index + 2) % 5].lower()
            else:
                return vowels[(index + 2) % 5].upper()
        return c

    encoded_message = ''
    for c in message:
        if c.isalpha():
            encoded_message += replace_vowel(swap_case(c))
        else:
            encoded_message += c

    return encoded_message

