class Solution:
    def get_max_k(self, arr, k):
        if not arr or k == 0:
            return []
        if k == 1:
            return arr

        # Initialize a min-heap
        heap = []
        for num in arr:
            heapq.heappush(heap, num)
            if len(heap) > k:
                heapq.heappop(heap)

        # The heap contains the k largest elements
        return heapq.nsmallest(k, heap)

